#include "insignia_attention.cuh"
#include <cuda_runtime.h>
#include <cmath>
#include <cstdio>
#include <vector>
#define OK(x) do{auto e=(x);if(e){printf("%s\n",cudaGetErrorString(e));return 2;}}while(0)
int main(){constexpr int T=257,H=16,KV=4,D=256;std::vector<float>q(H*D),k(T*KV*D),v(T*KV*D),ref(H*D),out(H*D);for(size_t i=0;i<q.size();i++)q[i]=float(int(i*7%31)-15)*.02f;for(size_t i=0;i<k.size();i++){k[i]=float(int(i*11%37)-18)*.015f;v[i]=float(int(i*5%29)-14)*.03f;}std::vector<double>s(T);for(int h=0;h<H;h++){double mx=-1e99;for(int t=0;t<T;t++){double z=0;for(int d=0;d<D;d++)z+=q[h*D+d]*k[(t*KV+h/4)*D+d];s[t]=z/16;mx=fmax(mx,s[t]);}double den=0;for(auto&z:s){z=exp(z-mx);den+=z;}for(int d=0;d<D;d++){double z=0;for(int t=0;t<T;t++)z+=s[t]/den*v[(t*KV+h/4)*D+d];ref[h*D+d]=float(z);}}float*dq,*dk,*dv,*dy;int*dpos;OK(cudaMalloc(&dq,q.size()*4));OK(cudaMalloc(&dk,k.size()*4));OK(cudaMalloc(&dv,v.size()*4));OK(cudaMalloc(&dy,out.size()*4));OK(cudaMalloc(&dpos,4));{int pos=T-1;OK(cudaMemcpy(dpos,&pos,4,cudaMemcpyHostToDevice));}OK(cudaMemcpy(dq,q.data(),q.size()*4,cudaMemcpyHostToDevice));OK(cudaMemcpy(dk,k.data(),k.size()*4,cudaMemcpyHostToDevice));OK(cudaMemcpy(dv,v.data(),v.size()*4,cudaMemcpyHostToDevice));insignia::gqa_decode(dq,dk,dv,dy,dpos,0,4096);OK(cudaDeviceSynchronize());OK(cudaMemcpy(out.data(),dy,out.size()*4,cudaMemcpyDeviceToHost));float e=0;for(size_t i=0;i<out.size();i++)e=fmaxf(e,fabsf(out[i]-ref[i]));printf("GQA decode T=%d max_abs=%g\n",T,e);return e<2e-5?0:1;}
